```

Instead of relying on the returned port mappings to hold references to the mock proxies, keep track of `StartProxy` calls in the test itself, e.g. by tracking the calls in a map keyed by the tuple of arguments and using [`is.DeepEqual`](https://pkg.go.dev/gotest.tools/v3@v3.5.1/assert/cmp#DeepEqual) to assert that all the expected `StartProxy` calls were made and no unexpected calls were included.
```go
type proxyCall struct { proto, host, container, proxyPath string }
proxies := map[proxyCall]*atomic.Bool // proxy -> is not stopped
startProxy = func(...) (func() error, error) {
	c := proxyCall{proto, fmt.Sprintf("%v:%v", hostIP, hostPort), fmt.Sprintf("%v:%v", containerIP, containerPort), proxyPath}
	if _, ok := proxies[c]; ok { return nil, fmt.Errorf("duplicate proxy: %#v", c) }
	proxies[c] = true
	return func() error {
		if tc.expReleaseErr != "" {
			return fmt.Errorf("can't stop now")
		}
		if !proxies[c] {
			return fmt.Errrof("already stopped")
		}
		proxies[c] = false
		return nil
	}
}
